import json, RNA
lines=json.load(open('/tmp/cands.json'))
target='((...((....((.....((.........((..............................))...............)).........)).......))....))....'
target_pairs=set()
st=[]
for i,c in enumerate(target):
    if c=='(':st.append(i)
    elif c==')': target_pairs.add((st.pop(),i))
best=None;best_d=9999
for s in lines:
    fc=RNA.fold_compound(s)
    ss,mfe=fc.mfe()
    # bp distance to target
    st=[];ss_pairs=set()
    for i,c in enumerate(ss):
        if c=='(':st.append(i)
        elif c==')': ss_pairs.add((st.pop(),i))
    # distance: missing + spurious
    d=len(target_pairs - ss_pairs)+len(ss_pairs-target_pairs)
    if d<best_d:
        best_d=d;best=(s,ss,mfe)
        if d==0:
            print('SOLVED',s);break
print('best_d',best_d)
print(best)
