import RNA
s=list('GGAAAGCAAAACCAAAAAGCCAAAAAAAAGCGAAAAAAAAAAAAAAAAAAAAAAAAAAAAAGCGAAAAAAAAAAAAGGGCGAAAAAAAGGGGAAAAAAGCAAAACCAAAA')
target='((...((....((.....((.........((..............................))...............)).........)).......))....))....'
print('pos20',s[20],'pos77',s[77])
fc=RNA.fold_compound(''.join(s))
ss,mfe=fc.mfe()
print(ss)
# try breaking: make 20 and 77 both A
for p20,p77 in [('A','A'),('A','U'),('U','A'),('A','G'),('G','A'),('U','U')]:
    t=s[:];t[20]=p20;t[77]=p77
    seq=''.join(t)
    fc=RNA.fold_compound(seq);ss,mfe=fc.mfe()
    st=[];sp=set()
    for i,c in enumerate(ss):
        if c=='(':st.append(i)
        elif c==')':sp.add((st.pop(),i))
    tt=[];tp=set()
    for i,c in enumerate(target):
        if c=='(':tt.append(i)
        elif c==')':tp.add((tt.pop(),i))
    d=len(tp-sp)+len(sp-tp)
    print(p20,p77,'d=',d,'mfe=',mfe)
    if d==0:
        print('SOLVED',seq)
